from pathlib import Path
from html import escape
from collections import OrderedDict

root=Path(__file__).parent
menu=OrderedDict()
for line in (root/'menu-data.tsv').read_text(encoding='utf-8').splitlines():
    if line and not line.startswith('#'):
        category,code,name,description,price,markers=line.split('|')
        menu.setdefault(category,[]).append((code,name,description,price,markers))

groups=['vorspeisen']*3+['hauptgerichte']*7+['spezialitaeten']+['nudelgerichte']*3+['dessert','mittag','kinder']+['getraenke']*7
ids=['vorspeisen','suppen','salate','vegetarisch','huhn','ente','rind','garnelen','gegrilltes','gebratenes','spezialitaeten','bun','mien','pho','dessert','mittag','kinder','specials','tee','softdrinks','bier','cocktails','wein','spirituosen']
sections=[]
for index,(category,items) in enumerate(menu.items()):
    entries=[]
    for code,name,description,price,markers in items:
        c=f'<span class="menu-code">{escape(code)}</span>' if code else '<span class="menu-code" aria-hidden="true"></span>'
        d=f'<p>{escape(description)}</p>' if description else ''
        m='' # Allergy number placements are not consistently legible in the supplied photos.
        entries.append(f'<div class="menu-entry">{c}<div class="menu-entry-main"><h3>{escape(name)} {m}</h3>{d}</div><span class="menu-entry-price">{escape(price)} €</span></div>')
    note='<p class="category-note">Montag – Freitag, 11:30 – 15:00 Uhr. Zu jedem Mittagsgericht 0,2 l Softgetränk für 1,50 € zusätzlich.</p>' if ids[index]=='mittag' else ''
    sections.append(f'<section class="menu-category" id="{ids[index]}" data-group="{groups[index]}"><div class="menu-category-head"><span>{index+1:02} / {len(menu):02}</span><h2>{escape(category)}</h2><span data-count>{len(items)} POSITIONEN</span></div>{note}<div class="menu-entry-list">{"".join(entries)}</div></section>')

html='''<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#0b0b0b"><meta name="description" content="Die vollständige Speisekarte von Viet Family: vietnamesische Vorspeisen, Phở, Bún, Reisgerichte, Desserts und Getränke mit Preisen."><title>Speisekarte — Viet Family</title><link rel="stylesheet" href="css/styles.css"><script defer src="js/main.js"></script><script defer src="js/menu.js"></script></head><body><a class="skip" href="#main">Zum Inhalt springen</a><header class="site-header scrolled"><a class="wordmark" href="index.html" aria-label="Viet Family, zur Startseite"><span>VIET<span class="brand-accent">.</span>FAMILY</span><small>ASIA KÜCHE RESTAURANT</small></a><nav class="desktop-nav" aria-label="Hauptnavigation"><a href="index.html#ueber">ÜBER UNS</a><a href="index.html#kueche">KÜCHE</a><a href="speisekarte.html">SPEISEKARTE</a><a href="index.html#restaurant">RESTAURANT</a><a href="index.html#info">INFO</a></nav><a class="header-action" href="index.html#besuch">BESUCHEN ↗</a><button class="menu-toggle" type="button" aria-label="Menü öffnen" aria-controls="mobile-nav" aria-expanded="false"><span></span><span></span></button></header><nav id="mobile-nav" class="mobile-nav" aria-label="Mobile Navigation" inert><div class="mobile-nav-head"><span>VIET.FAMILY</span><button class="menu-close" type="button" aria-label="Menü schließen">×</button></div><a href="index.html#ueber"><small>01</small> ÜBER UNS</a><a href="index.html#kueche"><small>02</small> KÜCHE</a><a href="speisekarte.html"><small>03</small> SPEISEKARTE</a><a href="index.html#restaurant"><small>04</small> RESTAURANT</a><a href="index.html#info"><small>05</small> INFO</a></nav><main id="main" class="subpage text-menu-page"><div class="section-kicker"><span>VIET FAMILY / SPEISEKARTE</span><a href="index.html">ZUR STARTSEITE ↗</a></div><h1>UNSERE<br>KARTE<span class="brand-accent">.</span></h1><p class="sublead">Vietnamesische Klassiker, Spezialitäten des Hauses und Getränke. Alle Gerichte sind auch zum Mitnehmen erhältlich.</p><div class="menu-tools"><nav class="menu-tabs" aria-label="Menügruppe wählen"><button type="button" data-menu-filter="vorspeisen" aria-pressed="true">VORSPEISEN</button><button type="button" data-menu-filter="hauptgerichte" aria-pressed="false">HAUPTGERICHTE</button><button type="button" data-menu-filter="nudelgerichte" aria-pressed="false">NUDELGERICHTE</button><button type="button" data-menu-filter="spezialitaeten" aria-pressed="false">SPEZIALITÄTEN</button><button type="button" data-menu-filter="dessert" aria-pressed="false">DESSERT</button><button type="button" data-menu-filter="mittag" aria-pressed="false">MITTAG</button><button type="button" data-menu-filter="kinder" aria-pressed="false">KINDER</button><button type="button" data-menu-filter="getraenke" aria-pressed="false">GETRÄNKE</button></nav><label class="menu-search"><span class="sr-only">Gerichte und Getränke suchen</span><input id="menu-search" type="search" placeholder="Gericht oder Zutat suchen" autocomplete="off"><span aria-hidden="true">⌕</span></label></div><p id="menu-status" class="menu-status" role="status" aria-live="polite"></p><div class="menu-text-content">'''+''.join(sections)+'''</div><p id="menu-empty" class="menu-empty" hidden>Keine passenden Einträge gefunden. Versuchen Sie einen anderen Suchbegriff.</p><div class="menu-endnote"><p><strong>Allergien & Unverträglichkeiten:</strong> Bitte fragen Sie vor der Bestellung im Restaurant nach den aktuellen Allergenangaben. Die Kennziffern der fotografierten Karte sind nicht in allen Fällen sicher lesbar.</p><a class="text-link" href="index.html#info">ÖFFNUNGSZEITEN ANSEHEN <span aria-hidden="true">↗</span></a></div></main><footer class="footer"><div class="footer-bottom"><span>© <span id="year">2026</span> VIET FAMILY</span><div><a href="rechtliches.html#impressum">IMPRESSUM</a><a href="rechtliches.html#datenschutz">DATENSCHUTZ</a></div><a href="index.html">STARTSEITE ↗</a></div></footer></body></html>'''
(root/'speisekarte.html').write_text(html,encoding='utf-8')
print(f'Built {len(menu)} categories, {sum(map(len,menu.values()))} entries')
